-- =============================================================================
-- AfriCodeShield - initial schema (phase 1)
-- PostgreSQL >= 16. Conventions:
--   * UUID primary keys (generated by the application, DB default as fallback)
--   * enum-like columns are VARCHAR + CHECK (portable, Hibernate-validate friendly)
--   * every timestamp is TIMESTAMPTZ (UTC)
--   * secrets are stored encrypted (AES-256-GCM) in BYTEA columns named *_ciphertext
-- See docs/data-model.md for the rationale of each table.
-- =============================================================================

-- ---------------------------------------------------------------------------
-- Git sources
-- ---------------------------------------------------------------------------
CREATE TABLE git_connection (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name                VARCHAR(120)  NOT NULL,
    provider_type       VARCHAR(32)   NOT NULL
        CHECK (provider_type IN ('GITLAB', 'GITHUB', 'BITBUCKET_CLOUD', 'BITBUCKET_DATA_CENTER', 'LOCAL')),
    base_url            VARCHAR(2048) NOT NULL,
    api_url             VARCHAR(2048),
    username            VARCHAR(255),
    -- AES-256-GCM(iv || ciphertext || tag); NULL for anonymous / local connections
    token_ciphertext    BYTEA,
    -- id of the master key used, to support key rotation
    token_key_id        VARCHAR(64),
    verify_tls          BOOLEAN       NOT NULL DEFAULT TRUE,
    enabled             BOOLEAN       NOT NULL DEFAULT TRUE,
    last_test_status    VARCHAR(32)
        CHECK (last_test_status IN ('OK', 'AUTHENTICATION_FAILED', 'INSUFFICIENT_PERMISSIONS', 'RATE_LIMITED',
                                    'NOT_FOUND', 'UNREACHABLE', 'TLS_ERROR', 'SERVER_ERROR', 'UNEXPECTED_RESPONSE')),
    last_test_message   VARCHAR(1000),
    last_tested_at      TIMESTAMPTZ,
    created_by          VARCHAR(255)  NOT NULL,
    created_at          TIMESTAMPTZ   NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ   NOT NULL DEFAULT now(),
    version             BIGINT        NOT NULL DEFAULT 0,
    CONSTRAINT uq_git_connection_name UNIQUE (name),
    CONSTRAINT ck_git_connection_token_key CHECK ((token_ciphertext IS NULL) = (token_key_id IS NULL))
);

-- Organisation / group / sub-group / workspace / project. "Score par organisation" = per namespace.
CREATE TABLE git_namespace (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    connection_id       UUID          NOT NULL REFERENCES git_connection (id) ON DELETE CASCADE,
    parent_id           UUID          REFERENCES git_namespace (id) ON DELETE CASCADE,
    external_id         VARCHAR(255)  NOT NULL,
    kind                VARCHAR(32)   NOT NULL
        CHECK (kind IN ('ORGANIZATION', 'GROUP', 'SUBGROUP', 'WORKSPACE', 'PROJECT', 'USER', 'LOCAL_DIRECTORY')),
    full_path           VARCHAR(1024) NOT NULL,
    name                VARCHAR(255)  NOT NULL,
    web_url             VARCHAR(2048),
    selected            BOOLEAN       NOT NULL DEFAULT FALSE,
    -- when TRUE every repository of the namespace (including future ones) is scanned
    include_all_repositories BOOLEAN  NOT NULL DEFAULT FALSE,
    discovered_at       TIMESTAMPTZ   NOT NULL DEFAULT now(),
    last_seen_at        TIMESTAMPTZ   NOT NULL DEFAULT now(),
    CONSTRAINT uq_git_namespace_external UNIQUE (connection_id, external_id)
);
CREATE INDEX ix_git_namespace_parent ON git_namespace (parent_id);

CREATE TABLE source_repository (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    connection_id       UUID          NOT NULL REFERENCES git_connection (id) ON DELETE CASCADE,
    namespace_id        UUID          REFERENCES git_namespace (id) ON DELETE SET NULL,
    external_id         VARCHAR(255)  NOT NULL,
    full_name           VARCHAR(1024) NOT NULL,
    name                VARCHAR(255)  NOT NULL,
    clone_url           VARCHAR(2048) NOT NULL,
    web_url             VARCHAR(2048),
    default_branch      VARCHAR(255),
    visibility          VARCHAR(16)
        CHECK (visibility IN ('PUBLIC', 'INTERNAL', 'PRIVATE')),
    archived            BOOLEAN       NOT NULL DEFAULT FALSE,
    selected            BOOLEAN       NOT NULL DEFAULT FALSE,
    -- DEFAULT: default branch only; PRESET: main/master/develop when they exist; CUSTOM: repository_branch rows
    branch_mode         VARCHAR(16)   NOT NULL DEFAULT 'DEFAULT'
        CHECK (branch_mode IN ('DEFAULT', 'PRESET', 'CUSTOM')),
    last_activity_at    TIMESTAMPTZ,
    discovered_at       TIMESTAMPTZ   NOT NULL DEFAULT now(),
    last_seen_at        TIMESTAMPTZ   NOT NULL DEFAULT now(),
    CONSTRAINT uq_source_repository_external UNIQUE (connection_id, external_id),
    CONSTRAINT ck_clone_url_no_credentials CHECK (clone_url !~ '^[a-zA-Z][a-zA-Z0-9+.-]*://[^/]*@')
);
CREATE INDEX ix_source_repository_namespace ON source_repository (namespace_id);
CREATE INDEX ix_source_repository_selected ON source_repository (selected) WHERE selected;

CREATE TABLE repository_branch (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    repository_id       UUID          NOT NULL REFERENCES source_repository (id) ON DELETE CASCADE,
    name                VARCHAR(255)  NOT NULL,
    enabled             BOOLEAN       NOT NULL DEFAULT TRUE,
    last_scanned_commit VARCHAR(64),
    last_scanned_at     TIMESTAMPTZ,
    CONSTRAINT uq_repository_branch UNIQUE (repository_id, name)
);

-- ---------------------------------------------------------------------------
-- Scanner configuration (global, one row per tool)
-- ---------------------------------------------------------------------------
CREATE TABLE scanner_config (
    scanner_id          VARCHAR(32)   PRIMARY KEY
        CHECK (scanner_id IN ('opengrep', 'trivy', 'gitleaks', 'pmd', 'checkstyle', 'dependency-check')),
    enabled             BOOLEAN       NOT NULL,
    timeout_seconds     INTEGER       NOT NULL CHECK (timeout_seconds BETWEEN 30 AND 21600),
    cpu_seconds         INTEGER       NOT NULL CHECK (cpu_seconds >= 1),
    memory_mb           INTEGER       NOT NULL CHECK (memory_mb >= 64),
    -- tool-specific options (rulesets, excluded paths...), validated by the adapter
    settings            JSONB         NOT NULL DEFAULT '{}'::jsonb,
    updated_by          VARCHAR(255),
    updated_at          TIMESTAMPTZ   NOT NULL DEFAULT now()
);

INSERT INTO scanner_config (scanner_id, enabled, timeout_seconds, cpu_seconds, memory_mb, settings) VALUES
    ('opengrep',         TRUE,  900,  1800, 2048, '{"rulesets": ["bundled"]}'),
    ('trivy',            TRUE,  900,  1800, 2048, '{"scanners": ["vuln", "misconfig"]}'),
    ('gitleaks',         TRUE,  600,  1200, 1024, '{}'),
    ('pmd',              TRUE,  900,  1800, 2048, '{"ruleset": "bundled-quickstart"}'),
    ('checkstyle',       TRUE,  600,  1200, 1024, '{"config": "bundled-sun-checks"}'),
    ('dependency-check', FALSE, 1800, 3600, 4096, '{}');

-- ---------------------------------------------------------------------------
-- Scheduling
-- ---------------------------------------------------------------------------
CREATE TABLE scan_schedule (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name                VARCHAR(120)  NOT NULL,
    -- Spring 6-field cron expression (second minute hour day month weekday)
    cron_expression     VARCHAR(120)  NOT NULL,
    time_zone           VARCHAR(64)   NOT NULL DEFAULT 'UTC',
    -- ALL_SELECTED: every selected repository; NAMESPACES / REPOSITORIES: rows in scan_schedule_target
    scope               VARCHAR(16)   NOT NULL DEFAULT 'ALL_SELECTED'
        CHECK (scope IN ('ALL_SELECTED', 'NAMESPACES', 'REPOSITORIES')),
    enabled             BOOLEAN       NOT NULL DEFAULT TRUE,
    skip_unchanged      BOOLEAN       NOT NULL DEFAULT TRUE,
    next_fire_at        TIMESTAMPTZ,
    last_fired_at       TIMESTAMPTZ,
    created_by          VARCHAR(255)  NOT NULL,
    created_at          TIMESTAMPTZ   NOT NULL DEFAULT now(),
    CONSTRAINT uq_scan_schedule_name UNIQUE (name)
);
CREATE INDEX ix_scan_schedule_due ON scan_schedule (next_fire_at) WHERE enabled;

CREATE TABLE scan_schedule_target (
    schedule_id         UUID NOT NULL REFERENCES scan_schedule (id) ON DELETE CASCADE,
    namespace_id        UUID REFERENCES git_namespace (id) ON DELETE CASCADE,
    repository_id       UUID REFERENCES source_repository (id) ON DELETE CASCADE,
    CONSTRAINT ck_schedule_target_one CHECK ((namespace_id IS NULL) <> (repository_id IS NULL))
);
CREATE UNIQUE INDEX uq_schedule_target_ns ON scan_schedule_target (schedule_id, namespace_id) WHERE namespace_id IS NOT NULL;
CREATE UNIQUE INDEX uq_schedule_target_repo ON scan_schedule_target (schedule_id, repository_id) WHERE repository_id IS NOT NULL;

-- ---------------------------------------------------------------------------
-- Execution: scan_run (one request) -> scan_job (one repository branch, queue unit)
--            -> scanner_execution (one tool on one job)
-- ---------------------------------------------------------------------------
CREATE TABLE scan_run (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    trigger_type        VARCHAR(16)   NOT NULL CHECK (trigger_type IN ('MANUAL', 'SCHEDULED', 'API')),
    schedule_id         UUID          REFERENCES scan_schedule (id) ON DELETE SET NULL,
    requested_by        VARCHAR(255)  NOT NULL,
    status              VARCHAR(16)   NOT NULL DEFAULT 'QUEUED'
        CHECK (status IN ('QUEUED', 'RUNNING', 'SUCCEEDED', 'PARTIAL', 'FAILED', 'CANCELLED')),
    total_jobs          INTEGER       NOT NULL DEFAULT 0,
    created_at          TIMESTAMPTZ   NOT NULL DEFAULT now(),
    started_at          TIMESTAMPTZ,
    finished_at         TIMESTAMPTZ
);
CREATE INDEX ix_scan_run_created ON scan_run (created_at DESC);

CREATE TABLE scan_job (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    scan_run_id         UUID          NOT NULL REFERENCES scan_run (id) ON DELETE CASCADE,
    repository_id       UUID          NOT NULL REFERENCES source_repository (id) ON DELETE CASCADE,
    branch              VARCHAR(255)  NOT NULL,
    commit_sha          VARCHAR(64),
    status              VARCHAR(16)   NOT NULL DEFAULT 'QUEUED'
        CHECK (status IN ('QUEUED', 'RUNNING', 'SUCCEEDED', 'PARTIAL', 'FAILED', 'CANCELLED')),
    priority            SMALLINT      NOT NULL DEFAULT 5 CHECK (priority BETWEEN 0 AND 9),
    attempt             SMALLINT      NOT NULL DEFAULT 0,
    max_attempts        SMALLINT      NOT NULL DEFAULT 2,
    -- lease for crash recovery: a RUNNING job whose lease expired is re-queued
    locked_by           VARCHAR(255),
    lease_expires_at    TIMESTAMPTZ,
    queued_at           TIMESTAMPTZ   NOT NULL DEFAULT now(),
    started_at          TIMESTAMPTZ,
    finished_at         TIMESTAMPTZ,
    error_message       VARCHAR(2000)
);
-- Queue polling: SELECT ... WHERE status='QUEUED' ORDER BY priority, queued_at FOR UPDATE SKIP LOCKED
CREATE INDEX ix_scan_job_queue ON scan_job (priority, queued_at) WHERE status = 'QUEUED';
CREATE INDEX ix_scan_job_lease ON scan_job (lease_expires_at) WHERE status = 'RUNNING';
CREATE INDEX ix_scan_job_run ON scan_job (scan_run_id);
CREATE INDEX ix_scan_job_repo_branch ON scan_job (repository_id, branch, finished_at DESC);
-- at most one active job per repository branch (concurrency control)
CREATE UNIQUE INDEX uq_scan_job_active ON scan_job (repository_id, branch) WHERE status IN ('QUEUED', 'RUNNING');

CREATE TABLE scanner_execution (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    scan_job_id         UUID          NOT NULL REFERENCES scan_job (id) ON DELETE CASCADE,
    scanner_id          VARCHAR(32)   NOT NULL,
    status              VARCHAR(16)   NOT NULL
        CHECK (status IN ('SUCCEEDED', 'FAILED', 'TIMED_OUT', 'SKIPPED', 'NOT_APPLICABLE')),
    tool_version        VARCHAR(120),
    -- version / date of the rules or vulnerability database used (required for reproducibility)
    ruleset_version     VARCHAR(255),
    exit_code           INTEGER,
    duration_ms         BIGINT,
    findings_count      INTEGER       NOT NULL DEFAULT 0,
    error_message       VARCHAR(2000),
    started_at          TIMESTAMPTZ,
    finished_at         TIMESTAMPTZ,
    CONSTRAINT uq_scanner_execution UNIQUE (scan_job_id, scanner_id)
);

-- ---------------------------------------------------------------------------
-- Findings: one row per distinct issue per repository branch (stable fingerprint),
-- one finding_occurrence per detection (scanner execution) -> history and diff between scans.
-- ---------------------------------------------------------------------------
CREATE TABLE finding (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    repository_id       UUID          NOT NULL REFERENCES source_repository (id) ON DELETE CASCADE,
    branch              VARCHAR(255)  NOT NULL,
    fingerprint         CHAR(64)      NOT NULL,
    type                VARCHAR(16)   NOT NULL CHECK (type IN ('SECURITY', 'QUALITY', 'SECRET', 'DEPENDENCY')),
    severity            VARCHAR(16)   NOT NULL CHECK (severity IN ('CRITICAL', 'HIGH', 'MEDIUM', 'LOW', 'INFO')),
    -- primary scanner / rule (the most severe report); all reporters are in finding_occurrence
    scanner_id          VARCHAR(32)   NOT NULL,
    rule_id             VARCHAR(512)  NOT NULL,
    title               VARCHAR(500)  NOT NULL,
    description         TEXT          NOT NULL DEFAULT '',
    cwe_ids             VARCHAR(16)[] NOT NULL DEFAULT '{}',
    cve_id              VARCHAR(64),
    cvss_score          NUMERIC(3, 1) CHECK (cvss_score BETWEEN 0 AND 10),
    cvss_vector         VARCHAR(255),
    file_path           VARCHAR(2048),
    start_line          INTEGER       CHECK (start_line >= 1),
    end_line            INTEGER,
    package_ecosystem   VARCHAR(64),
    package_name        VARCHAR(512),
    package_version     VARCHAR(128),
    fixed_version       VARCHAR(255),
    -- always redacted (SecretRedactor) before insert
    evidence_redacted   TEXT,
    recommendation      TEXT,
    references_urls     TEXT[]        NOT NULL DEFAULT '{}',
    commit_sha          VARCHAR(64),
    status              VARCHAR(16)   NOT NULL DEFAULT 'OPEN'
        CHECK (status IN ('OPEN', 'RESOLVED', 'ACCEPTED_RISK', 'FALSE_POSITIVE')),
    status_reason       VARCHAR(2000),
    status_changed_by   VARCHAR(255),
    status_changed_at   TIMESTAMPTZ,
    first_seen_job_id   UUID          REFERENCES scan_job (id) ON DELETE SET NULL,
    last_seen_job_id    UUID          REFERENCES scan_job (id) ON DELETE SET NULL,
    first_seen_at       TIMESTAMPTZ   NOT NULL DEFAULT now(),
    last_seen_at        TIMESTAMPTZ   NOT NULL DEFAULT now(),
    resolved_at         TIMESTAMPTZ,
    version             BIGINT        NOT NULL DEFAULT 0,
    CONSTRAINT uq_finding_fingerprint UNIQUE (repository_id, branch, fingerprint),
    CONSTRAINT ck_finding_fingerprint_hex CHECK (fingerprint ~ '^[0-9a-f]{64}$'),
    CONSTRAINT ck_finding_lines CHECK (end_line IS NULL OR start_line IS NULL OR end_line >= start_line),
    CONSTRAINT ck_finding_triage_reason CHECK (status NOT IN ('ACCEPTED_RISK', 'FALSE_POSITIVE')
                                               OR (status_reason IS NOT NULL AND status_changed_by IS NOT NULL))
);
CREATE INDEX ix_finding_repo_status ON finding (repository_id, branch, status);
CREATE INDEX ix_finding_severity_open ON finding (severity) WHERE status = 'OPEN';
CREATE INDEX ix_finding_cve ON finding (cve_id) WHERE cve_id IS NOT NULL;
CREATE INDEX ix_finding_package ON finding (package_name) WHERE package_name IS NOT NULL;

CREATE TABLE finding_occurrence (
    id                    UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    finding_id            UUID          NOT NULL REFERENCES finding (id) ON DELETE CASCADE,
    scanner_execution_id  UUID          NOT NULL REFERENCES scanner_execution (id) ON DELETE CASCADE,
    scan_job_id           UUID          NOT NULL REFERENCES scan_job (id) ON DELETE CASCADE,
    scanner_id            VARCHAR(32)   NOT NULL,
    rule_id               VARCHAR(512)  NOT NULL,
    reported_severity     VARCHAR(16)   NOT NULL
        CHECK (reported_severity IN ('CRITICAL', 'HIGH', 'MEDIUM', 'LOW', 'INFO')),
    file_path             VARCHAR(2048),
    start_line            INTEGER,
    end_line              INTEGER,
    detected_at           TIMESTAMPTZ   NOT NULL DEFAULT now(),
    CONSTRAINT uq_finding_occurrence UNIQUE (finding_id, scanner_execution_id, rule_id, file_path, start_line)
);
CREATE INDEX ix_finding_occurrence_job ON finding_occurrence (scan_job_id);

-- Human triage history (who changed what, why)
CREATE TABLE finding_status_history (
    id                  BIGSERIAL PRIMARY KEY,
    finding_id          UUID          NOT NULL REFERENCES finding (id) ON DELETE CASCADE,
    from_status         VARCHAR(16),
    to_status           VARCHAR(16)   NOT NULL,
    reason              VARCHAR(2000),
    changed_by          VARCHAR(255)  NOT NULL,
    changed_at          TIMESTAMPTZ   NOT NULL DEFAULT now()
);
CREATE INDEX ix_finding_status_history ON finding_status_history (finding_id, changed_at);

CREATE TABLE finding_remediation (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    finding_id          UUID          NOT NULL REFERENCES finding (id) ON DELETE CASCADE,
    provider_id         VARCHAR(120)  NOT NULL,
    generative          BOOLEAN       NOT NULL,
    content             JSONB         NOT NULL,
    created_at          TIMESTAMPTZ   NOT NULL DEFAULT now(),
    CONSTRAINT uq_finding_remediation UNIQUE (finding_id, provider_id)
);

-- ---------------------------------------------------------------------------
-- Scores (snapshots, so the dashboard can show trends)
-- ---------------------------------------------------------------------------
CREATE TABLE score_snapshot (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    scope_type          VARCHAR(16)   NOT NULL CHECK (scope_type IN ('GLOBAL', 'NAMESPACE', 'REPOSITORY', 'BRANCH')),
    namespace_id        UUID          REFERENCES git_namespace (id) ON DELETE CASCADE,
    repository_id       UUID          REFERENCES source_repository (id) ON DELETE CASCADE,
    branch              VARCHAR(255),
    scan_job_id         UUID          REFERENCES scan_job (id) ON DELETE SET NULL,
    -- NULL when coverage is too low to compute a meaningful score
    security_score      NUMERIC(5, 2) CHECK (security_score BETWEEN 0 AND 100),
    quality_score       NUMERIC(5, 2) CHECK (quality_score BETWEEN 0 AND 100),
    global_score        NUMERIC(5, 2) CHECK (global_score BETWEEN 0 AND 100),
    coverage_percent    NUMERIC(5, 2) NOT NULL CHECK (coverage_percent BETWEEN 0 AND 100),
    reliability         VARCHAR(16)   NOT NULL CHECK (reliability IN ('HIGH', 'MEDIUM', 'LOW', 'INSUFFICIENT')),
    formula_version     VARCHAR(32)   NOT NULL,
    -- counts per severity/type, scanners executed/missing, weights used
    details             JSONB         NOT NULL DEFAULT '{}'::jsonb,
    computed_at         TIMESTAMPTZ   NOT NULL DEFAULT now(),
    CONSTRAINT ck_score_scope CHECK (
        (scope_type = 'GLOBAL'     AND namespace_id IS NULL AND repository_id IS NULL AND branch IS NULL) OR
        (scope_type = 'NAMESPACE'  AND namespace_id IS NOT NULL AND repository_id IS NULL AND branch IS NULL) OR
        (scope_type = 'REPOSITORY' AND repository_id IS NOT NULL AND branch IS NULL) OR
        (scope_type = 'BRANCH'     AND repository_id IS NOT NULL AND branch IS NOT NULL))
);
CREATE INDEX ix_score_snapshot_scope ON score_snapshot (scope_type, namespace_id, repository_id, branch, computed_at DESC);

-- ---------------------------------------------------------------------------
-- Alerts and reports
-- ---------------------------------------------------------------------------
CREATE TABLE webhook_endpoint (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name                VARCHAR(120)  NOT NULL,
    url                 VARCHAR(2048) NOT NULL,
    -- HMAC-SHA256 signing secret, encrypted like git tokens
    secret_ciphertext   BYTEA,
    secret_key_id       VARCHAR(64),
    min_severity        VARCHAR(16)   NOT NULL DEFAULT 'CRITICAL'
        CHECK (min_severity IN ('CRITICAL', 'HIGH', 'MEDIUM', 'LOW', 'INFO')),
    events              VARCHAR(64)[] NOT NULL DEFAULT '{NEW_FINDINGS}',
    enabled             BOOLEAN       NOT NULL DEFAULT TRUE,
    created_by          VARCHAR(255)  NOT NULL,
    created_at          TIMESTAMPTZ   NOT NULL DEFAULT now(),
    CONSTRAINT uq_webhook_name UNIQUE (name),
    CONSTRAINT ck_webhook_secret_key CHECK ((secret_ciphertext IS NULL) = (secret_key_id IS NULL))
);

-- Transactional outbox: deliveries are written in the scan transaction and sent asynchronously
CREATE TABLE webhook_delivery (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    endpoint_id         UUID          NOT NULL REFERENCES webhook_endpoint (id) ON DELETE CASCADE,
    event_type          VARCHAR(64)   NOT NULL,
    payload             JSONB         NOT NULL,
    status              VARCHAR(16)   NOT NULL DEFAULT 'PENDING'
        CHECK (status IN ('PENDING', 'DELIVERED', 'FAILED')),
    attempts            SMALLINT      NOT NULL DEFAULT 0,
    next_attempt_at     TIMESTAMPTZ   NOT NULL DEFAULT now(),
    last_http_status    INTEGER,
    last_error          VARCHAR(1000),
    created_at          TIMESTAMPTZ   NOT NULL DEFAULT now(),
    delivered_at        TIMESTAMPTZ
);
CREATE INDEX ix_webhook_delivery_pending ON webhook_delivery (next_attempt_at) WHERE status = 'PENDING';

CREATE TABLE report (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    scan_run_id         UUID          REFERENCES scan_run (id) ON DELETE SET NULL,
    format              VARCHAR(8)    NOT NULL CHECK (format IN ('HTML', 'PDF', 'JSON', 'SARIF')),
    status              VARCHAR(16)   NOT NULL DEFAULT 'PENDING'
        CHECK (status IN ('PENDING', 'READY', 'FAILED')),
    -- path relative to the reports volume
    storage_path        VARCHAR(1024),
    sha256              CHAR(64),
    size_bytes          BIGINT,
    filters             JSONB         NOT NULL DEFAULT '{}'::jsonb,
    created_by          VARCHAR(255)  NOT NULL,
    created_at          TIMESTAMPTZ   NOT NULL DEFAULT now(),
    error_message       VARCHAR(2000)
);

-- ---------------------------------------------------------------------------
-- Settings and audit trail
-- ---------------------------------------------------------------------------
CREATE TABLE app_setting (
    key                 VARCHAR(120)  PRIMARY KEY,
    value               JSONB         NOT NULL,
    updated_by          VARCHAR(255),
    updated_at          TIMESTAMPTZ   NOT NULL DEFAULT now()
);

INSERT INTO app_setting (key, value) VALUES
    ('scoring.formula', '{"version": "v1-draft", "note": "Defined in phase 5, see docs/architecture.md#scoring"}'),
    ('worker.concurrency', '{"maxParallelJobs": 2}'),
    ('remediation.ollama', '{"enabled": false, "model": "qwen2.5-coder:7b"}');

-- Append-only log of security-relevant actions (connection changes, triage, settings...)
CREATE TABLE audit_event (
    id                  BIGSERIAL PRIMARY KEY,
    occurred_at         TIMESTAMPTZ   NOT NULL DEFAULT now(),
    actor_subject       VARCHAR(255)  NOT NULL,
    actor_username      VARCHAR(255),
    action              VARCHAR(64)   NOT NULL,
    target_type         VARCHAR(64),
    target_id           VARCHAR(255),
    details             JSONB         NOT NULL DEFAULT '{}'::jsonb,
    client_ip           VARCHAR(64)
);
CREATE INDEX ix_audit_event_time ON audit_event (occurred_at DESC);

CREATE FUNCTION audit_event_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'audit_event is append-only';
END;
$$;
CREATE TRIGGER tr_audit_event_immutable BEFORE UPDATE OR DELETE ON audit_event
    FOR EACH ROW EXECUTE FUNCTION audit_event_immutable();
